# MathError
# We want to define each variant as a nested class that's also a subclass,
# which is tricky in Python.  To accomplish this we're going to create each
# class separately, then manually add the child classes to the base class's
# __dict__.  All of this happens in dummy class to avoid polluting the module
# namespace.
class MathError(Exception):
    pass

_UniffiTempMathError = MathError

class MathError:  # type: ignore
    class DivisionByZero(_UniffiTempMathError):
        def __init__(self):
            pass

        def __repr__(self):
            return "MathError.DivisionByZero({})".format(str(self))
    _UniffiTempMathError.DivisionByZero = DivisionByZero # type: ignore
    class InvalidInput(_UniffiTempMathError):
        def __init__(self, message):
            super().__init__(", ".join([
                "message={!r}".format(message),
            ]))
            self.message = message

        def __repr__(self):
            return "MathError.InvalidInput({})".format(str(self))
    _UniffiTempMathError.InvalidInput = InvalidInput # type: ignore
    class NoRealSolution(_UniffiTempMathError):
        def __init__(self):
            pass

        def __repr__(self):
            return "MathError.NoRealSolution({})".format(str(self))
    _UniffiTempMathError.NoRealSolution = NoRealSolution # type: ignore
    class Overflow(_UniffiTempMathError):
        def __init__(self):
            pass

        def __repr__(self):
            return "MathError.Overflow({})".format(str(self))
    _UniffiTempMathError.Overflow = Overflow # type: ignore

MathError = _UniffiTempMathError # type: ignore
del _UniffiTempMathError


class _UniffiConverterTypeMathError(_UniffiConverterRustBuffer):
    @staticmethod
    def read(buf):
        variant = buf.read_i32()
        if variant == 1:
            return MathError.DivisionByZero(
            )
        if variant == 2:
            return MathError.InvalidInput(
                _UniffiConverterString.read(buf),
            )
        if variant == 3:
            return MathError.NoRealSolution(
            )
        if variant == 4:
            return MathError.Overflow(
            )
        raise InternalError("Raw enum value doesn't match any cases")

    @staticmethod
    def check_lower(value):
        if isinstance(value, MathError.DivisionByZero):
            return
        if isinstance(value, MathError.InvalidInput):
            _UniffiConverterString.check_lower(value.message)
            return
        if isinstance(value, MathError.NoRealSolution):
            return
        if isinstance(value, MathError.Overflow):
            return

    @staticmethod
    def write(value, buf):
        if isinstance(value, MathError.DivisionByZero):
            buf.write_i32(1)
        if isinstance(value, MathError.InvalidInput):
            buf.write_i32(2)
            _UniffiConverterString.write(value.message, buf)
        if isinstance(value, MathError.NoRealSolution):
            buf.write_i32(3)
        if isinstance(value, MathError.Overflow):
            buf.write_i32(4)



class _UniffiConverterSequenceDouble(_UniffiConverterRustBuffer):
    @classmethod
    def check_lower(cls, value):
        for item in value:
            _UniffiConverterDouble.check_lower(item)

    @classmethod
    def write(cls, value, buf):
        items = len(value)
        buf.write_i32(items)
        for item in value:
            _UniffiConverterDouble.write(item, buf)

    @classmethod
    def read(cls, buf):
        count = buf.read_i32()
        if count < 0:
            raise InternalError("Unexpected negative sequence length")

        return [
            _UniffiConverterDouble.read(buf) for i in range(count)
        ]

